import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int compile = s.nextInt(), runtime = s.nextInt(), n = s.nextInt();
        boolean invalid = false;
        int need = - 1;
        for (int i = 0; i < n; i++) {
            String module = s.next();
            int release = s.nextInt();
            String status;
            if (release > compile) {
                status = "INVALID_RELEASE";
                invalid = true;
            } else if (release > runtime) {
                status = "TOO_NEW";
                need = Math.max(need, release);
            } else status = "OK";
            System.out.println(module + " " + status);
        }
        System.out.println(invalid ? "FIX_BUILD" : need >= 0 ? "NEED_RUNTIME " + need : "ALL_OK");
    }
}

