import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        Map<String, String> tools = Map.of("experiment", "jshell", "bytecode", "javap", "dependencies", "jdeps", "runtime", "jlink", "installer", "jpackage");
        Map<String, String> actions = Map.of("standard", "CONSIDER", "preview", "EVALUATE", "deprecated", "MIGRATE", "removed", "BLOCK");
        int n = s.nextInt(), preview = 0, migrate = 0;
        for (int k = 1; k <= n; k++) {
            String goal = s.next(), state = s.next();
            if (state.equals("removed")) System.out.println(k + " BLOCK");
            else System.out.println(k + " " + tools.get(goal) + " " + actions.get(state));
            if (state.equals("preview")) preview++;
            if (state.equals("deprecated") || state.equals("removed")) migrate++;
        }
        System.out.println("PREVIEW " + preview);
        System.out.println("MIGRATE " + migrate);
    }
}
